dataset.prompt_raw_json:
{
  "parts": [
    {
      "text": "Quais documentos são obrigatórios para liberar uma viagem interestadual de transporte de grãos segundo as políticas de compliance da cooperativa?"
    }
  ],
  "role": "user"
}

dataset.reference_raw_json:
{
  "parts": [
    {
      "text": "Os documentos obrigatórios são CNH do motorista com EAR ativa, CRLV do veículo com licenciamento do ano corrente e cadastro ativo na ANTT/RNTRC."
    }
  ],
  "role": "model"
}

dataset.prompt_raw_json:
{
  "parts": [
    {
      "text": "Minha CNH venceu em 2023, posso liberar o carregamento para a viagem V-98214?"
    }
  ],
  "role": "user"
}

dataset.reference_raw_json:
{
  "parts": [
    {
      "text": "Não. CNHs vencidas bloqueiam a liberação da viagem segundo as regras de compliance da Rodacoop."
    }
  ],
  "role": "model"
}

dataset.response_raw_json:
{
  "parts": [
    {
      "text": "Não, de acordo com a nossa política de compliance (Seção 2.2. Do Motorista), a CNH deve ter \"Validade física da habilitação regular perante a base nacional do SENATRAN\". Como sua CNH venceu em 2023, ela não está válida, e a liberação do carregamento para a viagem V-98214 não poderá ser realizada."
    }
  ],
  "role": "model"
}

